 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"

/* Include the Exo-generated kernel header. */
#include "generated/lu/lu.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite. */
  /* not necessary for LU, but using same code as cholesky */
  int r,s,t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      (POLYBENCH_ARRAY(B))[r][s] = 0;
  for (t = 0; t < n; ++t)
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	(POLYBENCH_ARRAY(B))[r][s] += A[r][t] * A[s][t];
    for (r = 0; r < n; ++r)
      for (s = 0; s < n; ++s)
	A[r][s] = (POLYBENCH_ARRAY(B))[r][s];
  POLYBENCH_FREE_ARRAY(B);

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# ---------------------------------------------------------------------------
# Base LU factorization kernel.
# This matches the mathematical structure of the PolyBench LU kernel:
#   - First inner loop computes the L entries (A[i, j] for j < i).
#   - Second inner loop updates the current row (U part, j >= i).
# ---------------------------------------------------------------------------

@proc
def kernel_lu_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    for i in seq(0, n):
        # Compute L(i, j) for j < i
        for j in seq(0, i):
            for k in seq(0, j):
                A[i, j] += -A[i, k] * A[k, j]
            A[i, j] = A[i, j] / A[j, j]

        # Update U row: j ranges from i to n-1
        # This is a rank-1 style update of row i using previous rows.
        for j in seq(i, n):
            for k in seq(0, i):
                A[i, j] += -A[i, k] * A[k, j]


# ---------------------------------------------------------------------------
# Scheduled / optimized kernel.
#
# Transformations focus on the trailing-row update (the second j-loop):
#   1. Reorder the (j, k) loops in the U update to (k, j) so that:
#        - We iterate over k (panel index) outermost,
#        - Then traverse j (columns) contiguously in memory.
#      This improves spatial locality for both A[i, j] and A[k, j].
#
#   2. Shift the trailing j loop to start from 0 instead of i:
#        for j in seq(i, n)  -->  for j in seq(0, n - i)
#      with indices remapped to A[i, j + i], A[k, j + i].
#      This makes the loop amenable to tiling.
#
#   3. Tile (block) the trailing j dimension with a constant tile size:
#        for j in seq(0, n - i)  -->  for jo in ...: for ji in 0..TILE_J-1
#      This improves cache reuse on long rows by working on short
#      contiguous segments at a time.
#
#   4. Unroll the innermost ji loop to expose instruction-level parallelism.
#
#   The outer loop computing L (j < i) is left in its natural order,
#   because it has true data dependencies along j (each A[i, j] depends
#   on earlier A[i, k], k < j).
# ---------------------------------------------------------------------------

kernel_lu = kernel_lu_base

# 1) Reorder the trailing update from (j, k) to (k, j)
#    for better row-wise accesses to A[i, j] and A[k, j].
j_trailing = kernel_lu.find_loop("j #1")
kernel_lu = reorder_loops(kernel_lu, j_trailing)

# After this step, the structure is (schematically):
#   for i in 0..n:
#     for j in 0..i-1:        # L part
#       ...
#     for k in 0..i-1:        # U part (outer)
#       for j in i..n-1:      # U part (inner, contiguous in memory)
#         A[i, j] += -A[i, k] * A[k, j]

# 2) Shift the inner j loop in the U update so that it starts at 0.
#    This yields:
#       for j in seq(0, n - i):
#         A[i, j + i] += -A[i, k] * A[k, j + i]
j_trailing = kernel_lu.find_loop("j #1")
kernel_lu = shift_loop(kernel_lu, j_trailing, "0")

# 3) Tile (block) the shifted j dimension inside the U update.
#    TILE_J is a compile-time tuning parameter controlling the block size
#    along the row direction. It can be adjusted to match the L1/L2 cache.
TILE_J = 32

j_trailing = kernel_lu.find_loop("j #1")
kernel_lu = divide_loop(kernel_lu, j_trailing, TILE_J, ["jo", "ji"], tail="guard")

# Now the U update has the shape:
#   for i in 0..n:
#     ...
#     for k in 0..i-1:
#       for jo in 0..(n-i)/TILE_J:
#         for ji in 0..TILE_J-1:
#           # guarded inside for the tail when (n-i) is not a multiple of TILE_J
#           j = jo*TILE_J + ji
#           if j < n - i:
#               A[i, j + i] += -A[i, k] * A[k, j + i]

# 4) Unroll the innermost ji loop to expose ILP and enable better
#    vectorization by downstream C compilers.
ji_loop = kernel_lu.find_loop("ji")
kernel_lu = unroll_loop(kernel_lu, ji_loop)

# 5) Clean up the IR: simplify expressions and remove dead code
#    introduced by the transformations above (e.g., trivial arithmetic).
kernel_lu = simplify(kernel_lu)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_lu (/*ctxt=*/NULL, n,
             (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
