from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable compile-time blocking factors. These control the block size
# along the row (i) and column (j) dimensions. They are chosen to give
# reasonable cache and TLB behavior on typical x86-64 CPUs, but can be
# adjusted and the Exo scheduler re-run without changing the C driver.
BLOCK_I = 16
BLOCK_J = 32


@proc
def kernel_lu_base(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    """
    Baseline right-looking LU factorization without pivoting.

    The matrix A is overwritten in-place with its LU factors:
      - For i > j, A[i, j] holds L(i, j)
      - For i <= j, A[i, j] holds U(i, j)
    """
    for i in seq(0, n):
        # Compute the i-th column of L below the diagonal.
        for j in seq(0, i):
            for k in seq(0, j):
                # A[i, j] -= A[i, k] * A[k, j]
                A[i, j] += -A[i, k] * A[k, j]
            A[i, j] = A[i, j] / A[j, j]

        # Compute the i-th row of U, including the diagonal.
        for j in seq(i, n):
            for k in seq(0, i):
                # A[i, j] -= A[i, k] * A[k, j]
                A[i, j] += -A[i, k] * A[k, j]


# --------------------------------------------------------------------
# Scheduling for performance
# --------------------------------------------------------------------
# We keep the mathematical computation identical, but:
#  - Tile the outer i-loop to improve temporal locality of rows.
#  - Tile the j-loops to get better cache behavior over columns.
#  - Shift and tile the U-update j-loop so it can be parallelized.
#  - Parallelize the outer j-tile loop in the U-update with OpenMP.
#
# All transformations preserve the original sequential iteration order
# modulo harmless guarding code, so the numerical result remains
# equivalent to kernel_lu_base (up to FP roundoff).
# --------------------------------------------------------------------

kernel_lu_sched = kernel_lu_base

