# This improves locality when updating multiple nearby rows which share
# similar working sets in A.
kernel_lu_sched = divide_loop(
    kernel_lu_sched,
    kernel_lu_sched.find_loop("i"),
    BLOCK_I,
    ("io", "ii"),
)

# 2) Tile the j-loop of the lower-triangular (L) update.
# For each fixed i, accesses A[i, j] are along the row and contiguous
# in memory. Blocking j helps keep these row segments hot in cache.
kernel_lu_sched = divide_loop(
    kernel_lu_sched,
    kernel_lu_sched.find_loop("j"),  # first j-loop (L update)
    BLOCK_J,
    ("jLo", "jLi"),
)

# 3) For the upper-triangular (U) update, the original loop is:
#       for j in seq(i, n):
#   We first shift it to start from 0 so that the loop bound becomes
#   (n - i) and we can safely apply divide_loop with a constant block.
kernel_lu_sched = shift_loop(
    kernel_lu_sched,
    kernel_lu_sched.find_loop("j #1"),  # second j-loop (U update)
    "0",
)

