kernel_lu_sched = divide_loop(
    kernel_lu_sched,
    kernel_lu_sched.find_loop("j #1"),
    BLOCK_J,
    ("jUo", "jUi"),
)

# 5) Parallelize the outer j-tile loop in the U update.
#    For a fixed row i, different columns j are independent: each
#    iteration updates a distinct A[i, j] and only reads previously
#    computed rows. This exposes coarse-grain parallelism over columns.
kernel_lu_sched = parallelize_loop(
    kernel_lu_sched,
    kernel_lu_sched.find_loop("jUo"),
)

