def kernel_lu(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # PolyBench uses square matrices with n >= 1.
    assert n >= 1

    for i in seq(0, n):
        # Compute the L factors for row i (strictly lower-triangular part).
        for j in seq(0, i):
            # Gaussian elimination update: subtract previously computed L*U product.
            for k in seq(0, j):
                A[i, j] += -A[i, k] * A[k, j]
            # Normalize by the diagonal of U to obtain L(i, j).
            A[i, j] = A[i, j] / A[j, j]

        # Update the U row i (diagonal and upper-triangular part).
        for j in seq(i, n):
            for k in seq(0, i):
                A[i, j] += -A[i, k] * A[k, j]


# ---------------------------------------------------------------------------
# Scheduling / optimization phase
# ---------------------------------------------------------------------------

# Tile size for the outer i-loop (rows). This value can be tuned for the
# target machine's cache hierarchy.
TILE_I = 32

# Tile size for the inner j-loop in the upper-triangular update. This improves
# spatial locality when streaming across row elements A[i, j] and A[k, j].
TILE_J = 64

