    for i in seq(0, n):
        # Compute L factors: strict lower triangle A[i, j] for j < i.
        for j in seq(0, i):
            # Dot product against previously computed rows k < j.
            for k in seq(0, j):
                # A[i, j] -= A[i, k] * A[k, j]
                A[i, j] += -A[i, k] * A[k, j]
            # Normalize by the U diagonal A[j, j].
            A[i, j] = A[i, j] / A[j, j]

        # Compute U factors: upper triangle A[i, j] for j >= i.
        #
        # We iterate k outermost and sweep j contiguously to:
        #   1. Reuse A[i, k] across all j in [i, n)
        #   2. Access row i and row k with stride-1 along j
        for k in seq(0, i):
